import sys
import json
import re
from xml.etree import ElementTree as ET

def evaluate_expression(expr, data):
    try:
        # Replace JSON keys with their values
        for key in data:
            expr = expr.replace(f'{{{{{key}}}}}', str(data[key]))
        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, {'__import__': None})
    except Exception:
        return str(expr)

def render_template(template_str, data):
    def replace_match(match):
        expr = match.group(1).strip()
        return str(evaluate_expression(expr, data))

    pattern = re.compile(r'\{\{([^}]+)\}\}')
    return pattern.sub(replace_match, template_str)

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    template = root.find('template').text
    return template

def main():
    if len(sys.argv) != 2:
        print("Usage: python render_config.py PATH", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    template = parse_xml(xml_path)

    json_data = json.load(sys.stdin)
    rendered = render_template(template, json_data)
    print(rendered)

if __name__ == "__main__":
    main()
